// hello_server.ql
// -------------------------------------------------
// A tiny web server that replies with “Hello, World!”
// for GET requests to the root path (“/”).
// -------------------------------------------------

import net.http   // Quillon’s built‑in HTTP library

// Entry point of the program
fn main() -> Result<(), http.Error> {
    // 1️⃣ Create a server that will listen on all interfaces, port 8080
    let mut server = http.Server::new(
        addr   = "0.0.0.0:8080",   // listen address
        // Optional: you can set timeouts, TLS config, etc. here
    )?                            // `?` propagates any creation error

    // 2️⃣ Define a handler for GET /
    server.on_get(
        path   = "/",
        handler = fn(req: http.Request, mut res: http.Response) -> Result<(), http.Error> {
            // Set the response status line
            res.status = http.StatusOK          // 200

            // Optional: add a header to tell the client what we’re sending
            res.headers.insert(
                key   = "Content-Type",
                value = "text/plain; charset=utf-8"
            )?;

            // The body of the response
            res.body = b"Hello, World!"         // Quillon strings are UTF‑8; byte literals work too

            // Signal that we’re done handling this request
            Ok(())
        },
    )?                                            // propagate any registration error

    // 3️⃣ Start the server’s event loop (blocking call)
    println!("🚀 Quillon hello‑world server listening on http://0.0.0.0:8080")
    server.start()?                               // runs until the process is terminated

    Ok(())
}
```

